52	      if (c === '/' && c2 === '/') { state = 'line'; out += '  '; i++; continue; }
53	      if (c === '/' && c2 === '*') { state = 'block'; out += '  '; i++; continue; }
54	      if (c === "'") state = 'sq';
55	      else if (c === '"') state = 'dq';
56	      else if (c === '`') state = 'tpl';
57	      out += c;
58	    } else if (state === 'line') {
59	      if (c === '\n') { state = 'code'; out += c; } else out += ' ';
60	    } else if (state === 'block') {
61	      if (c === '*' && c2 === '/') { state = 'code'; out += '  '; i++; }
62	      else out += c === '\n' ? '\n' : ' ';
63	    } else {
64	      out += c;
65	      if (c === '\\') { out += c2 ?? ''; i++; }
66	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
67	        state = 'code';
68	      }
69	    }
70	  }
71	  return out;
72	}
