74	// The file reduced to the JS the browser actually runs, everything else blanked
75	// to spaces so offsets (and therefore line numbers) are unchanged. For HTML that
76	// is the inline `<script>` bodies only — markup and page text are not code, and a
77	// Leaflet snippet quoted in a `<pre>` is not a call site.
78	function codeView(file, raw) {
79	  if (!HTML.test(file)) return blankComments(raw);
80	  const noComments = raw.replace(/<!--[\s\S]*?-->/g, blank);
81	  let out = blank(noComments);
82	  const re = /<script\b[^>]*>([\s\S]*?)<\/script\s*>/gi;
83	  for (let m = re.exec(noComments); m; m = re.exec(noComments)) {
84	    const open = noComments.indexOf('>', m.index);
85	    if (open === -1) continue;
86	    const start = open + 1;
87	    const body = blankComments(m[1]);
88	    out = out.slice(0, start) + body + out.slice(start + body.length);
89	  }
90	  return out;
91	}
92	
93	const CLOSERS = { '(': ')', '[': ']', '{': '}' };
94	
95	// From `src[open]` (an opening bracket), return the index of its match, or -1.
96	// String- and template-aware so a bracket inside a URL or a caption never
97	// unbalances the walk.
98	function matchBracket(src, open) {
99	  const stack = [CLOSERS[src[open]]];
100	  for (let i = open + 1; i < src.length; i++) {
101	    const c = src[i];
102	    if (c === '"' || c === "'" || c === '`') {
103	      for (i++; i < src.length; i++) {
104	        if (src[i] === '\\') i++;
105	        else if (src[i] === c) break;
106	      }
107	      continue;
108	    }
109	    if (CLOSERS[c]) stack.push(CLOSERS[c]);
110	    else if (c === ')' || c === ']' || c === '}') {
111	      if (stack[stack.length - 1] !== c) return -1;
112	      stack.pop();
113	      if (stack.length === 0) return i;
114	    }
115	  }
116	  return -1;
117	}
118	
119	// Split `src[from..to)` on commas that sit at this level — nested calls, arrays,
120	// objects and string literals are stepped over whole.
121	function splitTopLevel(src, from, to) {
122	  const parts = [];
123	  let start = from;
124	  for (let i = from; i < to; i++) {
125	    const c = src[i];
126	    if (c === '"' || c === "'" || c === '`') {
127	      for (i++; i < to; i++) {
128	        if (src[i] === '\\') i++;
129	        else if (src[i] === c) break;
130	      }
131	      continue;
132	    }
133	    if (CLOSERS[c]) {
134	      const end = matchBracket(src, i);
135	      if (end === -1 || end >= to) return null;
136	      i = end;
137	      continue;
138	    }
139	    if (c === ',') { parts.push(src.slice(start, i)); start = i + 1; }
140	  }
141	  parts.push(src.slice(start, to));
142	  return parts;
143	}
144	
145	const KEY = /^\s*(?:(['"])([A-Za-z_$][\w$]*)\1|([A-Za-z_$][\w$]*))\s*:/;
146	
147	// The object literal's own top-level keys, or null when any member is a spread
148	// (`...defaults`) — a spread can carry `attribution` in, so the literal no longer
149	// proves its absence and the call is left alone.
150	function topLevelKeys(src, open) {
151	  const close = matchBracket(src, open);
152	  if (close === -1) return null;
153	  const members = splitTopLevel(src, open + 1, close);
154	  if (members === null) return null;
155	  const keys = [];
156	  for (const member of members) {
157	    if (member.trim() === '') continue;
158	    if (member.trim().startsWith('...')) return null;
159	    const m = KEY.exec(member);
160	    if (!m) continue;
161	    keys.push(m[2] ?? m[3]);
162	  }
163	  return keys;
164	}
165	
166	const rule = {
167	  id: 'leaflet/tile-attribution',
168	  severity: 'blocking',
169	  description: 'An L.tileLayer(...) built with a literal options object carries the tile provider\'s attribution',
170	  doc: 'packs/leaflet/RULES.md',
171	  why: 'the provider\'s attribution is a licence term, not decoration — an unattributed tile layer uses the tiles outside their terms, and nothing about the running map looks wrong, so a UI tidy-up drops it and no one notices',
172	
173	  run(ctx) {
174	    const out = [];
175	    for (const file of ctx.files) {
176	      if (!SOURCE.test(file)) continue;
177	      const raw = ctx.read(file);
178	      if (raw === null || !raw.includes('L.tileLayer')) continue;
179	      const src = codeView(file, raw);
180	      if (OUT_OF_BAND.test(src)) continue;
181	
182	      CALL.lastIndex = 0;
183	      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
184	        const open = m.index + m[0].length - 1;
185	        const close = matchBracket(src, open);
186	        if (close === -1) continue;
187	        const args = splitTopLevel(src, open + 1, close);
188	        if (args === null) continue;
189	
190	        const options = (args[1] ?? '').trim();
191	        if (args.length > 1) {
192	          // Not a literal — options come from a variable, a call, or a spread we
193	          // cannot see into. Absence here is not provable, so it is not judged.
194	          if (!options.startsWith('{')) continue;
195	          // Where args[1]'s own text begins in `src`, past its leading blanks.
196	          const objStart = open + 1 + args[0].length + 1
197	            + (args[1].length - args[1].trimStart().length);
198	          const keys = topLevelKeys(src, objStart);
199	          if (keys === null || keys.includes('attribution')) continue;
200	        }
201	
202	        out.push(finding(rule, {
203	          file,
204	          line: src.slice(0, m.index).split('\n').length,
205	          what: args.length > 1
206	            ? 'builds an L.tileLayer with a literal options object that has no `attribution`'
207	            : 'builds an L.tileLayer with no options at all, so no `attribution`',
208	          fix: 'add attribution to this layer\'s options — e.g. attribution: \'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors\' — or, where the credit is genuinely supplied elsewhere, register it through map.attributionControl.addAttribution(...)',
209	        }));
210	      }
211	    }
212	    return out;
213	  },
214	};
215	
216	export default rule;
