1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
3	
4	// Converted from this pack's exit-path prose: `NSApplication` installs no signal
5	// handlers, so a bare SIGTERM (Activity Monitor's Quit, `killall`), SIGINT or
6	// SIGHUP kills the process with no teardown at all — leaving a capture tap's
7	// CoreAudio IOProc registered on the device, which is what wedges some USB input
8	// devices until they are physically re-plugged.
9	//
10	// Gated twice, so it speaks only where the rule applies: the tree must be an
11	// AppKit app (a command-line tool has no `NSApp.terminate` to route into) AND it
12	// must install a capture tap (no tap, no IOProc to abandon, nothing at stake).
13	// Everything is read with comments stripped — prose describing the trap is not
14	// an implementation of it, nor evidence against one.
15	//
16	// Three arms:
17	//   1. nothing anywhere routes those signals — any of the three mechanisms a Mac
18	//      app plausibly uses counts as routing (`DispatchSource.makeSignalSource`,
19	//      `sigaction`, a direct `signal(SIGTERM, …)` handler);
20	//   2. routing exists but one of the three signals is named nowhere in the
21	//      sources — the unrouted one stays fatal by default;
22	//   3. `SIG_IGN` comes after the source is resumed — until the default action is
23	//      ignored, a signal landing in the gap still terminates the process outright.
24	//
25	// Arm 3 compares offsets rather than parsing scopes, and deliberately only looks
26	// at the first `.resume()` that follows the file's first `makeSignalSource(` — an
27	// unrelated `resume()` earlier in the file (a URLSession task, a dispatch queue)
28	// is then not this rule's business.
29	//
30	// Blocking: every arm describes a path that skips teardown silently, and the
31	// damage shows up on hardware rather than in the build.
32	
33	const SWIFT = /\.swift$/;
34	
35	const SIGNALS = ['SIGTERM', 'SIGINT', 'SIGHUP'];
36	
37	// AppKit, not a CLI: only an app with an NSApplication has NSApp.terminate to
38	// route into, and only it gets `applicationWillTerminate` at all.
39	const APPKIT = /\bNSApplicationDelegate\b|\bNSApplicationMain\b|\bNSApp\b/;
40	// A capture tap is what registers the IOProc this rule protects.
41	const TAP = /\binstallTap\s*\(/;
42	
43	const MAKE_SOURCE = /\bmakeSignalSource\s*\(/;
44	const ROUTING = [
45	  MAKE_SOURCE,
46	  /\bsigaction\s*\(/,
47	  new RegExp(`\\bsignal\\s*\\(\\s*(?:${SIGNALS.join('|')})\\b`),
48	];
49	const SIG_IGN = /\bsignal\s*\([^)]*SIG_IGN/;
50	const RESUME = /\.resume\s*\(\s*\)/g;
51	
52	const lineOf = (text, index) => text.slice(0, index).split('\n').length;
53	
54	const rule = {
55	  id: 'signal-teardown-routing',
56	  severity: 'blocking',
57	  description: 'An AppKit app that installs a capture tap routes SIGTERM/SIGINT/SIGHUP into NSApp.terminate, with SIG_IGN before resume() (*.swift)',
58	  doc: 'packs/macos/RULES.md',
59	  why: 'NSApplication installs no signal handlers, so an unrouted SIGTERM/SIGINT/SIGHUP kills the process with no teardown and abandons the capture tap\'s IOProc on the device — the state that wedges some USB input devices until they are re-plugged',
60	
61	  run(ctx) {
62	    const sources = new Map();
63	    for (const file of ctx.files.filter((f) => SWIFT.test(f))) {
64	      const text = ctx.read(file);
65	      if (text !== null) sources.set(file, stripComments(text));
66	    }
67	
68	    const isApp = [...sources.values()].some((t) => APPKIT.test(t));
69	    const tapSite = [...sources.entries()].find(([, t]) => TAP.test(t));
70	    if (!isApp || !tapSite) return [];
71	
72	    const routingFiles = [...sources.entries()].filter(([, t]) => ROUTING.some((r) => r.test(t)));
73	
74	    if (routingFiles.length === 0) {
75	      const [file, text] = tapSite;
76	      return [finding(rule, {
77	        file,
78	        line: lineOf(text, text.search(TAP)),
79	        what: `a capture tap is installed in ${file} but nothing in the sources routes termination signals to NSApp.terminate`,
80	        fix: 'map [SIGTERM, SIGINT, SIGHUP] to `DispatchSource.makeSignalSource(signal:queue:)` handlers that call `NSApp.terminate(nil)` — calling `signal(sig, SIG_IGN)` before `resume()`, and holding the sources in a top-level `let` so they outlive setup',
81	      })];
82	    }
83	
84	    const out = [];
85	
86	    // Arm 2: a signal named nowhere in the sources is a signal nothing routes.
87	    const unrouted = SIGNALS.filter(
88	      (s) => ![...sources.values()].some((t) => new RegExp(`\\b${s}\\b`).test(t))
89	    );
90	    if (unrouted.length > 0) {
91	      const [file, text] = routingFiles[0];
92	      out.push(finding(rule, {
93	        file,
94	        line: lineOf(text, Math.max(text.search(MAKE_SOURCE), 0)),
95	        what: `signal routing exists but ${unrouted.join(', ')} appears nowhere in the sources`,
96	        fix: `route ${unrouted.join(', ')} the same way as the signals already handled — each of them is fatal by default and leaves the tap installed`,
97	      }));
98	    }
99	
100	    // Arm 3: SIG_IGN must precede the resume() of the sources it protects.
101	    for (const [file, text] of routingFiles) {
102	      const setup = text.search(MAKE_SOURCE);
103	      if (setup < 0) continue;
104	      RESUME.lastIndex = setup;
105	      const resumed = RESUME.exec(text);
106	      if (resumed === null) continue;
107	      const ignore = text.search(SIG_IGN);
108	      if (ignore >= 0 && ignore < resumed.index) continue;
109	      out.push(finding(rule, {
110	        file,
111	        line: lineOf(text, resumed.index),
112	        what: ignore < 0
113	          ? `${file} resumes a signal source without ever calling signal(…, SIG_IGN)`
114	          : `${file} calls signal(…, SIG_IGN) only after resume()`,
115	        fix: 'call `signal(sig, SIG_IGN)` before `source.resume()` — until the default action is ignored, a signal arriving in the gap still terminates the process outright',
116	      }));
117	    }
118	
119	    return out;
120	  },
121	};
122	
123	export default rule;
