4	const rule = {
5	  id: 'gha/secrets-in-job-if',
6	  severity: 'blocking',
7	  description: 'A job-level if: cannot read secrets.* — the job fails red instead of skipping',
8	  doc: 'skills/git-github-advanced/SKILL.md',
9	  why: 'secrets are not available in a job-level if:, so the condition cannot evaluate and the job fails instead of skipping',
10	
11	  run(ctx) {
12	    const out = [];
13	    for (const wf of workflowFiles(ctx)) {
14	      const text = ctx.read(wf);
15	      if (text === null) continue;
16	      // An if: at or above the current steps: indent is job-level; below it is step-level.
17	      let stepsIndent = -1;
18	      text.split('\n').forEach((line, i) => {
