20	        if (steps) { stepsIndent = steps[1].length; return; }
21	        if (/^\s{0,2}\S/.test(line)) stepsIndent = -1; // new job or top-level key
22	        const m = /^(\s*)if:\s*(.*)$/.exec(line);
23	        if (m && /secrets\./.test(m[2]) && (stepsIndent === -1 || m[1].length <= stepsIndent)) {
24	          out.push(finding(rule, {
25	            file: wf, line: i + 1,
26	            what: `job-level if: reads ${/secrets\.\w+/.exec(m[2])?.[0] ?? 'secrets.*'}`,
27	            fix: 'put the non-sensitive flag in a repository variable and gate with vars.* (if: ${{ vars.X != \'\' }}); keep the secret for the steps inside the job',
28	          }));
29	        }
30	      });
31	    }
32	    return out;
33	  },
34	};
