4	// A single | between non-| characters is a shell pipe; || is the or-operator.
5	const PIPE = /(^|[^|])\|([^|]|$)/;
6	
7	const rule = {
8	  id: 'gha/run-pipefail',
9	  severity: 'blocking',
10	  description: 'A workflow piping in run: steps needs shell: bash — the default shell has no pipefail',
11	  doc: 'skills/git-github-advanced/SKILL.md',
12	  why: "GitHub's implicit run shell is bash -e without pipefail, so a failing piped command still shows the step green",
13	
14	  run(ctx) {
15	    const out = [];
16	    for (const wf of workflowFiles(ctx)) {
17	      const text = ctx.read(wf);
18	      if (text === null || /shell:\s*bash/.test(text)) continue;
19	      const lines = text.split('\n');
20	      for (let i = 0; i < lines.length; i += 1) {
21	        const inline = /^(\s*)(?:-\s+)?run:\s*(.+)$/.exec(lines[i]);
22	        if (!inline) continue;
23	        const runIndent = inline[1].length;
24	        let commands = [];
25	        if (/^[|>][+-]?\s*$/.test(inline[2])) {
26	          for (let j = i + 1; j < lines.length; j += 1) {
27	            if (lines[j].trim() && !/^\s+/.test(lines[j])) break;
28	            if (lines[j].trim() && lines[j].search(/\S/) <= runIndent) break;
29	            commands.push(lines[j]);
30	            if (!lines[j].trim()) continue;
31	          }
32	        } else {
33	          commands = [inline[2]];
34	        }
35	        if (commands.some((c) => PIPE.test(c))) {
36	          out.push(finding(rule, {
37	            file: wf, line: i + 1,
38	            what: 'a piped run: step in a workflow with no bash shell default',
39	            fix: 'add defaults.run.shell: bash (workflow- or job-level) so the step runs with -o pipefail',
40	          }));
41	        }
42	      }
43	    }
44	    return out;
45	  },
46	};
