4	// Converted from the aws-sam prose (issue #136): under BuildMethod: esbuild with a
5	// single subdirectory entry point and no OutBase, esbuild's default outbase is the
6	// entry's own dir, so the subdirectory is dropped from the artifact — the Handler
7	// must not carry it (`handler.handler`, not `src/handler.handler`). Wrong value
8	// fails only at first invoke with Runtime.ImportModuleError. Blocking.
9	//
10	// FP guards (from adversarial mining): skip when OutBase is set (it changes the
11	// drop) or when there is more than one entry point (behavior differs).
12	const rule = {
13	  id: 'aws-sam/handler-path',
14	  severity: 'blocking',
15	  description: 'A SAM esbuild single-entry Handler must not carry the entry subdirectory',
16	  doc: 'packs/aws-sam/RULES.md',
17	  why: "esbuild's default outbase is the entry's own dir, so the subdir is stripped from the artifact and a subdir Handler fails at invoke",
18	
19	  run(ctx) {
20	    const out = [];
21	    for (const { templatePath, name, resource } of samResources(ctx)) {
22	      if (resource.Type !== 'AWS::Serverless::Function') continue;
23	      const meta = resource.Metadata;
24	      if (!meta || meta.BuildMethod !== 'esbuild') continue;
25	      const bp = meta.BuildProperties;
26	      const entries = bp && Array.isArray(bp.EntryPoints) ? bp.EntryPoints : null;
27	      if (!entries || entries.length !== 1) continue; // multiple/none: behavior differs
28	      if (bp.OutBase != null) continue; // OutBase overrides the subdir drop
29	      const entry = String(entries[0]);
30	      const slash = entry.lastIndexOf('/');
31	      if (slash === -1) continue; // no subdir to drop
32	      const subdir = entry.slice(0, slash);
33	      const handler = resource.Properties && resource.Properties.Handler;
34	      if (typeof handler === 'string' && handler.startsWith(`${subdir}/`)) {
35	        out.push(finding(rule, {
36	          file: templatePath,
37	          what: `${name}: Handler "${handler}" keeps the "${subdir}/" prefix esbuild drops`,
38	          fix: `set Handler to "${handler.slice(subdir.length + 1)}" (esbuild writes the bundle to the artifact root), or set BuildProperties.OutBase if you intend to keep the subdir`,
39	        }));
40	      }
41	    }
42	    return out;
43	  },
44	};
