33	// `source` with comment text blanked, and — when `strings` is set — string and
34	// template bodies too (newlines kept, so line numbers never shift). The entry
35	// block is judged with strings blanked, so prose describing the trap or a code
36	// sample in a template literal cannot fire it; the import walk needs the
37	// specifiers intact, so it reads the comments-only form.
38	function blank(source, { strings = true } = {}) {
39	  let out = '';
40	  let i = 0;
41	  while (i < source.length) {
