89	  if (at === -1) return null;
90	  const open = code.indexOf('{', at);
91	  if (open === -1) return null;
92	  let depth = 0;
93	  for (let i = open; i < code.length; i += 1) {
94	    if (code[i] === '{') depth += 1;
95	    else if (code[i] === '}') {
96	      depth -= 1;
97	      if (depth === 0) return { text: code.slice(open, i + 1), open };
98	    }
