103	const rule = {
104	  id: 'pack-discovery-entry-await',
105	  severity: 'blocking',
106	  description: 'No module a pack manifest or skill checks.mjs imports awaits at the top level of its CLI-entry block',
107	  doc: '.claudinite/local/packs/claudinite/RULES.md',
108	  why: 'pack discovery imports every pack.mjs and skills/*/checks.mjs on disk before activation is consulted, so such a module is re-imported mid-evaluation when it is also the entry point — the top-level await then never settles and Node exits 13 having run nothing, silently (#581)',
