110	  run(ctx) {
111	    const seeds = ctx.tracked.filter((f) => SEED.test(f)).sort();
112	    if (seeds.length === 0) return []; // no pack tree here — nothing to judge
113	    const tracked = new Set(ctx.tracked);
114	
115	    const seen = new Set();
116	    const queue = [...seeds];
117	    const out = [];
118	    while (queue.length > 0) {
119	      const file = queue.shift();
120	      if (seen.has(file)) continue;
121	      seen.add(file);
122	      const source = ctx.read(file);
123	      if (source === null) continue;
124	      const code = blank(source);
