126	      const block = entryBlock(code);
127	      // An `async` inside the block means an async function or IIFE owns the
128	      // await, which does not hold module evaluation open — stay quiet rather
129	      // than guess at nesting. Conservative by design: this rule blocks, so it
130	      // may only fire on the shape it is certain about.
131	      if (block && AWAIT.test(block.text) && !/(?:^|[^\w.$])async[\s(]/.test(block.text)) {
132	        const line = code.slice(0, block.open + block.text.search(AWAIT)).split('\n').length;
133	        out.push(finding(rule, {
134	          file,
135	          line,
136	          what: `${file} awaits at the top level of its CLI-entry block, and pack discovery imports it`,
137	          fix: 'start the work after module evaluation completes instead — `doWork(...).catch((e) => process.stderr.write(...))` — never `await doWork(...)` at the top level of the entry block',
