141	      for (const m of blank(source, { strings: false }).matchAll(IMPORT)) {
142	        const spec = m[1];
143	        if (!spec.startsWith('.')) continue;
144	        const target = resolveFrom(file, spec);
145	        if (tracked.has(target)) queue.push(target);
