1	import { dirname, join, basename } from 'node:path';
2	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
3	
4	// A routine (or a per-project-scheduling task, §1) is a folder whose entry point is
5	// `routine.md` OR `task.md`, alongside the deterministic scripts it invokes. This
6	// check asserts the prose↔script wiring that the unattended-agents skill mandates,
7	// for both shapes: a legacy `dev/routines/<name>/routine.md` and a converted
8	// `.../tasks/<name>/task.md` earn the same guard (a task folder's `task.mjs`
9	// carries the declaration; its `task.md` is the worker prose the scripts hang off).
10	//
11	// RELEVANCE FIRST (see engine/checks/README.md "Adding a rule"): a skill check has no
12	// declaration gate — the engine runs it on EVERY repo, including ones with no
13	// routines — so `run` must detect relevance before asserting anything. Here the
14	// signal is a `routine.md`/`task.md` existing: `routineDirs` is empty on any repo
15	// without one, every loop below is over an empty set, and the check no-ops. Keep
16	// that gate narrow and up front; a broad signal would fire false findings everywhere.
17	const ENTRY_NAMES = ['routine.md', 'task.md'];
18	const isEntry = (f) => ENTRY_NAMES.includes(basename(f));
19	const PHASE_SCRIPTS = ['preconditions.sh', 'postconditions.sh'];
20	
21	// Direct-child files of dir `d` within `files` matching `pred` (not descendants).
22	function children(files, d, pred) {
23	  const prefix = d ? d + '/' : '';
24	  return files.filter((f) => {
25	    if (!f.startsWith(prefix)) return false;
26	    const rel = f.slice(prefix.length);
27	    return rel.length > 0 && !rel.includes('/') && pred(rel);
28	  });
29	}
30	
31	const rule = {
32	  id: 'routine-structure',
33	  severity: 'blocking',
34	  description: 'A routine/task folder has a routine.md or task.md entry point wired to the scripts it invokes',
35	  doc: 'skills/unattended-agents/SKILL.md',
36	  why: 'a routine is prose (read) + scripts (executed); a dangling invocation or an orphan/entry-less script means the agent runs the wrong thing or the job hides where it is never read',
37	
38	  run(ctx) {
39	    const out = [];
40	    const files = ctx.files;
41	
42	    // dir -> its entry file name (routine.md or task.md). A folder carries one or
43	    // the other; if it somehow had both, the first wins (they wire the same scripts).
44	    const entryOf = new Map();
45	    for (const f of files.filter(isEntry)) {
46	      const d = dirname(f);
47	      if (!entryOf.has(d)) entryOf.set(d, basename(f));
48	    }
49	    const routineDirs = new Set(entryOf.keys());
50	
51	    for (const [dir, ENTRY] of entryOf) {
52	      const text = ctx.read(join(dir, ENTRY));
53	      if (text === null) continue;
54	      const lines = text.split('\n');
55	      const scripts = children(files, dir, (rel) => rel.endsWith('.sh'));
56	
57	      // 1. Every `bash …/x.sh` the prose tells you to run must resolve.
58	      lines.forEach((ln, i) => {
59	        const m = /\b(?:bash|sh)\s+(\S+\.sh)\b/.exec(ln);
60	        if (!m) return;
61	        const p = m[1];
62	        if (ctx.exists(p) || ctx.exists(join(dir, p))) return;
63	        out.push(finding(rule, {
64	          file: join(dir, ENTRY), line: i + 1,
65	          what: `invokes ${p}, which does not exist`,
66	          fix: 'correct the path or restore the script; a routine must not tell the agent to run a missing file',
67	        }));
68	      });
69	
70	      // 2. Every script in the folder must be invoked by the entry point — an
71	      //    uninvoked script is dead weight or an indirection that never ran.
72	      for (const s of scripts) {
73	        if (text.includes(basename(s))) continue;
74	        out.push(finding(rule, {
75	          file: s, line: null, severity: 'advisory',
76	          what: `is never invoked by ${join(dir, ENTRY)}`,
77	          fix: `invoke it from ${ENTRY}, or remove it — a script the routine never runs does not earn its place`,
78	        }));
79	      }
80	
81	      // 3. Each script must be a real executable script (shebang first line).
82	      for (const s of scripts) {
83	        const body = ctx.read(s);
84	        if (body === null || body.startsWith('#!')) continue;
85	        out.push(finding(rule, {
86	          file: s, line: 1, severity: 'advisory',
87	          what: 'has no shebang line',
88	          fix: 'start the script with a shebang (e.g. #!/usr/bin/env bash) so it runs standalone',
89	        }));
90	      }
91	    }
92	
93	    // 4. A folder carrying phase scripts but no routine.md/task.md has lost its
94	    //    entry point — the standard name is how the routine or task is found and run.
95	    const phaseDirs = new Set(
96	      files.filter((f) => PHASE_SCRIPTS.includes(basename(f))).map((f) => dirname(f)),
97	    );
98	    for (const dir of phaseDirs) {
99	      if (routineDirs.has(dir)) continue;
100	      out.push(finding(rule, {
101	        file: join(dir, PHASE_SCRIPTS.find((n) => ctx.exists(join(dir, n))) || PHASE_SCRIPTS[0]),
102	        line: null,
103	        what: `sits in a routine folder with no ${ENTRY_NAMES.join(' / ')} entry point`,
104	        fix: `add ${ENTRY_NAMES.join(' or ')} as the folder's entry point (it invokes these scripts), or move the scripts out`,
105	      }));
106	    }
107	
108	    return out;
109	  },
110	};
111	
112	export default rule;
