1	// A MINIMAL YAML-subset parser — dependency-free, sufficient to query the
2	// STRUCTURE of SAM/CloudFormation templates (nested block maps, block and flow
3	// sequences, scalars). Deliberately NOT a general YAML parser:
4	//   - no anchors/aliases, no multi-line block scalars (| >), no flow maps
5	//   - CloudFormation short tags (!Ref, !Sub, !GetAtt …) keep their scalar value,
6	//     the tag is dropped
7	//   - it never throws: on anything it can't parse it returns what it has (or null)
8	// Good enough for the SAM/CloudFormation template checks; do not use it for
9	// arbitrary YAML.
10	
11	function stripComment(line) {
12	  let q = null;
13	  for (let i = 0; i < line.length; i += 1) {
14	    const c = line[i];
15	    if (q) { if (c === q) q = null; continue; }
16	    if (c === '"' || c === "'") { q = c; continue; }
17	    if (c === '#' && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
18	  }
19	  return line;
20	}
21	
22	function scalar(rawIn) {
23	  let raw = rawIn.trim();
24	  if (raw === '' || raw === '~' || raw === 'null') return null;
25	  if (raw === 'true') return true;
26	  if (raw === 'false') return false;
27	  if (raw[0] === '!') {
28	    // CloudFormation tag: drop the tag word, keep the value
29	    const sp = raw.indexOf(' ');
30	    raw = sp === -1 ? '' : raw.slice(sp + 1).trim();
31	    if (raw === '') return null;
32	  }
33	  if ((raw[0] === '"' && raw.at(-1) === '"') || (raw[0] === "'" && raw.at(-1) === "'")) {
34	    return raw.slice(1, -1);
35	  }
36	  if (raw[0] === '[') return flowSeq(raw);
37	  if (/^-?\d+$/.test(raw)) return Number(raw);
38	  if (/^-?\d*\.\d+$/.test(raw)) return Number(raw);
39	  return raw;
40	}
41	
42	function flowSeq(raw) {
43	  const inner = raw.slice(1, raw.lastIndexOf(']')).trim();
44	  if (inner === '') return [];
45	  return inner.split(',').map((s) => scalar(s.trim()));
46	}
47	
48	const isSeq = (t) => t === '-' || t.startsWith('- ');
49	
50	// Parse the block whose sibling lines all sit at lines[i].indent; returns [value, next].
51	function parseBlock(lines, i) {
52	  const indent = lines[i].indent;
53	
54	  if (isSeq(lines[i].text)) {
55	    const arr = [];
56	    while (i < lines.length && lines[i].indent === indent && isSeq(lines[i].text)) {
57	      const rest = lines[i].text === '-' ? '' : lines[i].text.slice(2).trim();
58	      if (rest === '') {
59	        if (i + 1 < lines.length && lines[i + 1].indent > indent) {
60	          const [v, ni] = parseBlock(lines, i + 1); arr.push(v); i = ni;
61	        } else { arr.push(null); i += 1; }
62	      } else if (splitKey(rest)) {
63	        // "- key: value" (+ deeper lines) → a map item
64	        const sub = [{ indent: indent + 2, text: rest }];
65	        let j = i + 1;
66	        while (j < lines.length && lines[j].indent > indent) { sub.push(lines[j]); j += 1; }
67	        const [v] = parseBlock(sub, 0); arr.push(v); i = j;
68	      } else { arr.push(scalar(rest)); i += 1; }
69	    }
70	    return [arr, i];
71	  }
72	
73	  const obj = {};
74	  while (i < lines.length && lines[i].indent === indent && !isSeq(lines[i].text)) {
75	    const kv = splitKey(lines[i].text);
76	    if (!kv) { i += 1; continue; } // not a key: line we understand — skip it
77	    const [key, rest] = kv;
78	    if (rest === '') {
79	      if (i + 1 < lines.length && lines[i + 1].indent > indent) {
80	        const [v, ni] = parseBlock(lines, i + 1); obj[key] = v; i = ni;
81	      } else { obj[key] = null; i += 1; }
82	    } else { obj[key] = scalar(rest); i += 1; }
83	  }
84	  return [obj, i];
85	}
86	
87	// Split "key: rest" at the first unquoted colon followed by space or end-of-line.
88	function splitKey(text) {
89	  let q = null;
90	  for (let i = 0; i < text.length; i += 1) {
91	    const c = text[i];
92	    if (q) { if (c === q) q = null; continue; }
93	    if (c === '"' || c === "'") { q = c; continue; }
94	    if (c === ':' && (i + 1 === text.length || text[i + 1] === ' ')) {
95	      let key = text.slice(0, i).trim();
96	      if ((key[0] === '"' && key.at(-1) === '"') || (key[0] === "'" && key.at(-1) === "'")) key = key.slice(1, -1);
97	      return [key, text.slice(i + 1).trim()];
98	    }
99	  }
100	  return null;
101	}
102	
103	export function parseYaml(text) {
104	  try {
105	    const lines = [];
106	    for (const raw of text.split('\n')) {
107	      const nc = stripComment(raw);
108	      if (nc.trim() === '') continue;
109	      if (/^(---|\.\.\.)\s*$/.test(nc.trim())) continue;
110	      lines.push({ indent: nc.length - nc.trimStart().length, text: nc.trim() });
111	    }
112	    if (!lines.length) return null;
113	    return parseBlock(lines, 0)[0];
114	  } catch {
115	    return null; // never throw — a check that can't parse simply finds nothing
116	  }
117	}
