1	// Helpers for checks that scan source *code* for a forbidden token (a banned
2	// API, an impure import, a DOM specific). Such a check must see code, not
3	// prose: a comment or a doc-string that merely *names* `chrome.storage` or
4	// `fetch(` is describing the code, not doing it, and matching it is a false
5	// positive that fails the build over an English sentence. Strip comments first.
6	
7	// Return `source` with its JS/TS comments removed, leaving everything else —
8	// including string and template literals — byte-for-byte intact. String-aware
9	// on purpose: a `//` inside "https://…" is not a comment, and dropping the rest
10	// of that line would corrupt real code (and could hide a genuine violation that
11	// follows on the same line). Regex literals are treated as code and preserved.
12	// Newlines inside block comments are kept so line numbers don't shift.
13	export function stripComments(source) {
14	  let out = '';
15	  let state = 'code'; // code | line | block | sq | dq | tpl
16	  for (let i = 0; i < source.length; i++) {
17	    const c = source[i];
18	    const c2 = source[i + 1];
19	    if (state === 'code') {
20	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
21	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
22	      if (c === "'") state = 'sq';
23	      else if (c === '"') state = 'dq';
24	      else if (c === '`') state = 'tpl';
25	      out += c;
26	    } else if (state === 'line') {
27	      if (c === '\n') { state = 'code'; out += c; }
28	    } else if (state === 'block') {
29	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
30	      else if (c === '\n') out += c;
31	    } else {
32	      // Inside a string/template literal: copy through until the matching quote,
33	      // honoring backslash escapes so an escaped quote doesn't end it early.
34	      out += c;
35	      if (c === '\\') { out += c2 ?? ''; i++; }
36	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
37	        state = 'code';
38	      }
39	    }
40	  }
41	  return out;
42	}
