4	// The two fixed paths the whole standard hangs off: the index README and the
5	// human-reviewed product-requirements sink. Wiki folders are NOT required (a
6	// sink-first scaffold is legitimate) and neither is sample-data/ (an exclusion
7	// in the classifier, not an obligation). A path satisfies the check when it is
8	// tracked OR freshly written and not yet staged (ctx.files carries untracked
9	// files) — a mid-session scaffold must not wedge the Stop hook into
10	// re-creating files that already exist.
11	const REQUIRED = [INDEX_README, SINK_README];
12	
