14	  id: 'product-wiki-layout',
15	  severity: 'blocking',
16	  doc: 'packs/product-wiki/README.md',
17	  description: 'A product-wiki repo carries the product-wiki/ skeleton: the index README and the reviewed product-requirements sink',
18	  why: 'a declared standard with no scaffold silently enforces nothing — the isolation wall and the wiki discipline both hang off these fixed paths',
19	
