26	          what: `the product-wiki standard requires ${path} but it does not exist`,
27	          fix: "scaffold it per the template in packs/product-wiki/README.md, or remove the product-wiki declaration if this repo doesn't adopt the standard",
28	        }));
29	      }
30	    }
31	    return out;
32	  },
33	};
