1	import { posix } from 'node:path';
2	import { finding } from '../../engine/checks/helpers/findings.mjs';
3	import { packEntryId } from '../../engine/pack_loader/pack-registry.mjs';
4	import { RULES_INDEX_FILE, RULES_INDEX_IMPORT } from '../../engine/pack_loader/generate-rules-index.mjs';
5	
6	// The rules index is the ONLY channel a pack's prose reaches a session on (#807). The
7	// SessionStart prose step that used to carry it is gone, deliberately — one channel, so
8	// no session can be running on a stale copy of one while the other is fine.
9	//
10	// That single channel is what makes this check load-bearing rather than tidy. Every
11	// converge writes the index, but a repo whose converge has stopped, whose CLAUDE.md was
12	// hand-edited, or that declared a pack since its last refresh has NO pack rules at all —
13	// and the loss is invisible from inside the session, which is precisely the property
14	// #807 was filed about. Going red is the only signal available: an agent cannot notice
15	// rules it never received.
16	//
17	// BLOCKING, and not by habit — an advisory would be read past by the very session that
18	// is missing the rules that would have told it not to.
19	//
20	// WHY IT DOES NOT RE-RENDER THE INDEX AND DIFF IT. The generator is async (loading a
21	// manifest is a dynamic import) and `runRule` spreads its result synchronously, so a
22	// rule cannot await. It also should not: rendering here would make the check agree with
23	// the generator by construction and test nothing. So this asks the questions that can
24	// be answered from the repo's own files — is there an index, does anything load it, does
25	// every import resolve, and is every DECLARED pack in it — and the canon's own
26	// `engine-tests/rules-index.test.mjs` holds the exact-content comparison.
27	//
28	// A subset test on purpose: the `requires` closure puts packs in the index that the
29	// declaration never names, so "every declared pack appears" cannot false-positive on a
30	// correct index, while still catching the case that matters — a pack declared since the
31	// last converge, whose rules are simply not loading.
32	const rule = {
33	  id: 'rules-index-current',
34	  severity: 'blocking',
35	  description: `${RULES_INDEX_FILE} must exist, import every declared pack's rules, and be imported by CLAUDE.md`,
36	  doc: 'vendoring/DESIGN.md',
37	  why: 'it is the only channel a pack\'s rules reach a session on; missing, stale or unimported means the session silently runs with none',
38	
39	  run(ctx) {
40	    const declared = Array.isArray(ctx.config?.packs) ? ctx.config.packs : [];
41	
42	    // RELEVANCE FIRST, like the scheduling guards beside it: the subject of this rule
43	    // is the index that OUGHT to exist, so if nothing would go in it there is nothing
44	    // to demand. A repo whose declared packs have no prose on disk has not converged
45	    // its mount yet — a different problem, already reported by the engine's own
46	    // unknown-pack error, and one this rule would only add noise to.
47	    //
48	    // `RULES.md` is spelled here rather than read off each manifest because a rule
49	    // cannot await a dynamic import (see above). It is safe: `prose` is only ever
50	    // 'RULES.md' or null across the whole corpus, and `every pack's prose is RULES.md
51	    // or null` in engine-tests/rules-index.test.mjs is what keeps it so.
52	    const heldIds = declared.map(packEntryId).filter((id) => id && [
53	      `.claudinite/shared/packs/${id}/RULES.md`, // a consumer's vendored mount
54	      `packs/${id}/RULES.md`,                    // the canon, which mounts nothing
55	      `.claudinite/local/packs/${id}/RULES.md`,  // the repo's own packs
56	      `.claudinite/local_packs/${id}/RULES.md`,  // …and their pre-rename location
57	    ].some((p) => ctx.exists(p)));
58	    if (!heldIds.length) return [];
59	
60	    const regenerate = 'run `node .claudinite/shared/engine/pack_loader/generate-rules-index.mjs --write` (canon-side: `node engine/pack_loader/generate-rules-index.mjs --write`) and commit the result';
61	    const findings = [];
62	
63	    const index = ctx.read(RULES_INDEX_FILE);
64	    if (index === null) {
65	      findings.push(finding(rule, {
66	        file: RULES_INDEX_FILE,
67	        what: 'the rules index is missing, so no pack\'s RULES.md loads into a session',
68	        fix: regenerate,
69	      }));
70	    } else {
71	      // Bare `@path` lines — the only thing this file holds, and the only shape the
72	      // harness follows (an import inside backticks is skipped).
73	      const imports = index.split('\n')
74	        .map((l) => l.trim())
75	        .filter((l) => l.startsWith('@') && !l.includes('`'))
76	        .map((l) => l.slice(1));
77	
78	      for (const rel of imports) {
79	        // Resolved from the index's OWN directory, because that is what the harness
80	        // resolves against — the canon's imports climb out of `.claudinite/` with
81	        // `..`, so this has to normalize rather than concatenate. A dangling import is
82	        // #807 in a new costume: the channel works, the rules still do not arrive, and
83	        // nothing says so.
84	        if (!ctx.exists(posix.normalize(posix.join('.claudinite', rel)))) {
85	          findings.push(finding(rule, {
86	            file: RULES_INDEX_FILE,
87	            what: `the index imports \`${rel}\`, which does not exist — that pack's rules load as nothing`,
88	            fix: regenerate,
89	          }));
90	        }
91	      }
92	
93	      // Every declared pack this repo HOLDS prose for must be imported. Gated on
94	      // held-ness so the rule agrees with the generator, which skips a pack whose
95	      // files are not vendored rather than emitting a dangling import.
96	      for (const id of heldIds) {
97	        if (!imports.some((rel) => rel.includes(`/packs/${id}/`))) {
98	          findings.push(finding(rule, {
99	            file: RULES_INDEX_FILE,
100	            what: `pack "${id}" is declared and its RULES.md is here, but the rules index does not import it — those rules never load`,
101	            fix: regenerate,
102	          }));
103	        }
104	      }
105	    }
106	
107	    // The import must be matched OUTSIDE code spans: the harness skips `@` mentions in
108	    // backticks, so a CLAUDE.md that merely documents the line is one it never follows —
109	    // and reading that as wired would be the silent failure again in a new place.
110	    const claudeMd = ctx.read('CLAUDE.md');
111	    const imported = claudeMd !== null && claudeMd.split('\n')
112	      .some((line) => !line.includes('`') && line.includes(RULES_INDEX_IMPORT));
113	    if (!imported) {
114	      findings.push(finding(rule, {
115	        file: 'CLAUDE.md',
116	        what: `CLAUDE.md does not import ${RULES_INDEX_FILE}, so nothing loads it`,
117	        fix: `add the line \`${RULES_INDEX_IMPORT}\` to CLAUDE.md — outside backticks, or the harness will not follow it`,
118	      }));
119	    }
120	    return findings;
121	  },
122	};
123	
124	export default rule;
