37	function distance(fromDir, toDir) {
38	  const a = fromDir === '.' ? [] : fromDir.split('/');
39	  const b = toDir === '.' ? [] : toDir.split('/');
40	  let common = 0;
41	  while (common < a.length && common < b.length && a[common] === b[common]) common += 1;
42	  return (a.length - common) + (b.length - common);
43	}
