8	// Every line in `files` where `re` matches: [{ file, line, text }], 1-indexed,
9	// ready to anchor findings. Pass a non-global regex.
10	export function matchingLines(ctx, files, re) {
11	  const out = [];
12	  for (const f of files) {
13	    const text = ctx.read(f);
14	    if (text === null) continue;
15	    text.split('\n').forEach((ln, i) => {
16	      if (re.test(ln)) out.push({ file: f, line: i + 1, text: ln });
17	    });
18	  }
19	  return out;
20	}
