22	// Every line the current change ADDED (vs the scoping base) across `files` —
23	// defaults to every in-scope file the change touched. The "changed lines of
24	// the current pull request": a check-the-work rule scans these to judge the
25	// work itself instead of re-auditing the world, so legacy state the change
26	// never touched stays quiet (the same scoping the squash-merge effect check
27	// uses).
28	export function addedLines(ctx, files = ctx.changedFiles) {
29	  return files.flatMap((f) => ctx.addedLines(f).map((l) => ({ file: f, ...l })));
