391	  const diffBase = mergeBase || 'HEAD';
392	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
393	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
394	  // be on it, so nothing is filtered out.
395	  const onBaseBranch = (sha) =>
396	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
