398	  const tracked = lines(gitTry(root, 'ls-files'));
399	  const untracked = lines(gitTry(root, 'ls-files', '--others', '--exclude-standard'));
400	
401	  const vsBase = lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase));
402	  let scanned;
403	  if (mode === 'all') {
404	    scanned = [...tracked, ...untracked];
405	  } else {
406	    scanned = [...new Set([...vsBase, ...untracked])];
407	  }
408	  // The vendored corpus under the shared mount is canon-owned, never the
409	  // project's own code — structurally out of scope for every check, on any git
410	  // host and any checkout (deliberately not attribute-driven). The consumer's
411	  // own .claudinite/local_packs/ sits BESIDE the shared mount and stays fully
412	  // in scope.
413	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
414	  // with the platform separator, so normalize before prefix-matching.
415	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
416	  scanned = scanned.filter((f) => !f.startsWith(sharedPrefix));
417	  // Every in-scope regular file, vendored/generated included.
418	  const allFiles = scanned.filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile());
