420	  // project's OWN authored code and every check skips them for free (see vendoredSet).
421	  const vendored = vendoredSet(root, allFiles);
422	  const files = allFiles.filter((f) => !vendored.has(f));
423	  // The in-scope files the current change touched (vs the scoping base),
424	  // untracked included — the file set behind lines.mjs addedLines, for
425	  // check-the-work rules that judge the work rather than re-audit the world.
426	  const changedSet = new Set([...vsBase, ...untracked]);
427	  const changedFiles = files.filter((f) => changedSet.has(f));
