450	  return {
451	    root,
452	    mode,
453	    baseRef,
454	    mergeBase,
455	    files,
456	    allFiles,
457	    changedFiles,
458	    tracked,
459	    deleted,
460	    commits,
461	    branch,
462	    config: loadConfig(root),
463	
464	    exists: (path) => existsSync(join(root, path)),
465	    read(path) {
