493	      let lineNo = 0;
494	      for (const l of (out || '').split('\n')) {
495	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
496	        if (hunk) { lineNo = Number(hunk[1]); continue; }
497	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
