499	      }
500	      return added;
501	    },
502	
503	    // Parsed transcript entries of the session driving this run, or null when no
504	    // transcript is available (see conversationCache above).
505	    conversation() {
506	      if (conversationCache !== undefined) return conversationCache;
507	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
508	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
509	      catch { conversationCache = null; }
510	      return conversationCache;
511	    },
512	
513	    // The branch's own commits since the merge-base, oldest first, each with its
514	    // changed files and committer date — for rules about the ORDER work landed in
515	    // (ctx.commits keeps only messages). Merges excluded: their file list is
516	    // empty under --name-only and their content arrives via their parents.
517	    commitsWithFiles() {
518	      if (!mergeBase) return [];
519	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
520	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase}..HEAD`);
521	      const commits = [];
522	      for (const block of (out || '').split('\0')) {
523	        if (!block.trim()) continue;
524	        const [head, ...rest] = block.trim().split('\n');
525	        const [sha, date, subject] = head.split('\x1f');
526	        commits.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
527	      }
528	      return commits;
529	    },
530	
531	    // Merge commits the current change introduces — those on HEAD's first-parent
532	    // chain since the merge-base with the base branch (the squash-only effect
533	    // check, scoped to the work). Empty when no base resolves or the branch is
534	    // even with it; pre-existing merges already on the base are out of range.
535	    //
536	    // The range alone trusts the merge-base to be right, and it isn't always: a
537	    // shallow clone's grafted boundary or a criss-cross history can hand back a
538	    // merge-base that sweeps the base branch's own merges into the range. So each
539	    // candidate is confirmed against the base ref itself — a merge already on the
540	    // base branch was never introduced here, whatever the range says. Offline and
541	    // exact, and it holds when refreshBaseRef couldn't run.
542	    introducedMergeCommits() {
543	      if (!mergeBase) return [];
544	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
545	      return lines(out).map((l) => {
546	        const i = l.indexOf(' ');
547	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
548	      }).filter(({ sha }) => !onBaseBranch(sha));
549	    },
550	
551	    // Fixed-string search across tracked files; git grep exits 1 on no match.
552	    // The vendored shared mount is structurally out of the sweep (canon-owned,
553	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
554	    // excluded here exactly as it is from the scanned file set above: a hit
555	    // inside it must never become a finding.
556	    grepTracked(needle) {
557	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
558	      return lines(out).map((l) => {
559	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
560	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
561	      }).filter(Boolean);
562	    },
563	  };
564	}
