75	  get packs() { return this.ctx.packs ?? []; }
76	  get config() { return this.ctx.config; }
77	  read(path) { return this.ctx.read(path); }
78	  readBase(path) { return this.ctx.readBase(path); }
79	  exists(path) { return this.ctx.exists(path); }
80	  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }
81	
82	  conversation() { return new Conversation(this.ctx.conversation()); }
83	
84	  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }
