103	  }
104	
105	  filesContaining(needle, files = this.ctx.files) {
106	    return files.filter((f) => (this.ctx.read(f) ?? '').includes(needle));
107	  }
108	
109	  // Relative Markdown links that resolve to nothing: [{ file, line, target, resolved }].
