142	const PATH_CHAR = /[\w./@-]/;
143	
144	function widenToken(text, start, end) {
145	  let s = start;
146	  let e = end;
147	  while (s > 0 && PATH_CHAR.test(text[s - 1])) s--;
148	  while (e < text.length && PATH_CHAR.test(text[e])) e++;
149	  return text.slice(s, e);
150	}
151	
152	function referencesSurvivingPath(hit, gone, ctx) {
153	  let idx = hit.text.indexOf(gone);
154	  if (idx === -1) return false;
155	  while (idx !== -1) {
156	    const token = widenToken(hit.text, idx, idx + gone.length);
157	    const resolved = normalize(join(dirname(hit.file), token));
158	    if (!((token !== gone && ctx.exists(token)) || ctx.exists(resolved))) return false;
159	    idx = hit.text.indexOf(gone, idx + 1);
160	  }
161	  return true;
162	}
