1	// Python-packaging knowledge the two optional-dependency checks share: which
2	// packages THIS repo declared optional, and how a distribution name maps to the
3	// import name a .py file would write. This is policy specific to the rules, not
4	// engine mechanism (that lives in engine/checks/helpers per the #351 lesson) — so it stays
5	// here beside the rules, imported by both. The checks runner only loads
6	// checks.mjs, so this module is inert to skill discovery.
7	
8	// The distribution names under [project.optional-dependencies] in a
9	// pyproject.toml's text. Line-based (the engine carries no TOML parser): find
10	// the section header, and until the next top-level [header] collect the leading
11	// package token of every quoted requirement string. Inside that section every
12	// quoted token is a requirement (the extra-group keys — `yamnet = [ ... ]` —
13	// are unquoted), so this needs no value/key discrimination. Handles the
14	// standard table form (grounded in missingbulb/LaughCounter). The rarer inline
15	// form — `optional-dependencies = { extra = [...] }` under [project] — is not
16	// parsed: a safe false-negative (nothing flagged), never a false-positive.
17	export function optionalDistNames(tomlText) {
18	  const names = new Set();
19	  let inSection = false;
20	  for (const raw of tomlText.split('\n')) {
21	    const header = /^\s*\[([^\]]+)\]/.exec(raw);
22	    if (header) { inSection = header[1].trim() === 'project.optional-dependencies'; continue; }
23	    if (!inSection) continue;
24	    for (const m of raw.matchAll(/["']([^"']+)["']/g)) {
25	      const name = /^[A-Za-z0-9][A-Za-z0-9._-]*/.exec(m[1].trim());
26	      if (name) names.add(name[0].toLowerCase());
27	    }
28	  }
29	  return names;
30	}
31	
32	// The import top-level package name(s) a set of dist names could appear as.
33	// Conservative: the name itself, plus '-'/'.' → '_' (the PEP 503-ish normal
34	// form, e.g. tensorflow-hub → tensorflow_hub). A dist whose import name is
35	// unrelated to its name (Pillow→PIL, opencv-python→cv2, scikit-learn→sklearn,
36	// PyYAML→yaml) is deliberately NOT mapped — so it simply isn't flagged, a safe
37	// false-negative, never a false-positive on an unrelated top-level import.
38	export function importNamesFor(distSet) {
39	  const imports = new Set();
40	  for (const d of distSet) {
41	    imports.add(d);
42	    imports.add(d.replace(/[-.]/g, '_'));
43	  }
44	  return imports;
45	}
46	
47	// The top-level package names an `import`/`from` statement pulls in, lowercased
48	// for comparison against importNamesFor's set. `from a.b import c` → a (a
49	// relative `from . import x` yields nothing); `import a.b as x, c` → a, c.
50	// Callers strip trailing comments before passing the line.
51	export function topPackagesOf(importLine) {
52	  const line = importLine.trim();
53	  let m;
54	  if ((m = /^from\s+([.\w]+)\s+import\b/.exec(line))) {
55	    return m[1].startsWith('.') ? [] : [m[1].split('.')[0].toLowerCase()];
56	  }
57	  if ((m = /^import\s+(.+)$/.exec(line))) {
58	    return m[1].split(',')
59	      .map((part) => part.trim().split(/\s+as\s+/)[0].trim().split('.')[0].toLowerCase())
60	      .filter((name) => name && !name.startsWith('.'));
61	  }
62	  return [];
63	}
