78	// The `contributedRules` seam's body: every ACTIVE pack's barrier
79	// contributions, built into first-class rules. Only the list the runner hands
80	// over is consulted — an undeclared pack contributes nothing, exactly as its
81	// own rules would not run.
82	export function contributedBarrierRules(activePacks) {
83	  const rules = [];
