8	  let open = null;
9	  let m;
10	  while ((m = re.exec(line)) !== null) {
11	    if (!open) open = { start: m.index, fence: m[0] };
12	    else if (m[0] === open.fence) { spans.push([open.start, m.index + m[0].length]); open = null; }
