21	    if (/^\s*(```|~~~)/.test(line)) { inFence = !inFence; return; }
22	    if (inFence) return;
23	    const spans = codeSpans(line);
24	    let m;
25	    LINK.lastIndex = 0;
26	    while ((m = LINK.exec(line)) !== null) {
27	      const at = m.index;
28	      if (spans.some(([s, e]) => at >= s && at < e)) continue;
