3	// The corpus's import-surface facts, in one home: how to find a module file's
4	// relative import specifiers, how to resolve one against a known file set
5	// (tree-oracle style, like the reference resolution the checks already use),
6	// and which paths form the ENGINE SURFACE — the always-vendored core every
7	// consumer carries whatever packs it declares. The vendor writer's coherence
8	// guard judges against these definitions; the `pack-independence` barrier
9	// (packs may import only their own files and this surface — barriers config
10	// contributed by the canon home's curation local pack) states the same surface
11	// as its allow list, so "what a pack may import" and "what a vendor set must
12	// carry" stay one idea with the barrier failing closed on any drift.
13	
14	// The one root that vendors wholesale into every consumer (vendoring/DESIGN.md):
15	// the whole engine — hooks, loaders, checks helpers, the mount machinery — lives
16	// under engine/, so "engine surface" and "always vendored" are the same test.
17	export const ENGINE_DIR_ROOTS = ['engine'];
18	
19	// Is this canon-relative path part of the engine surface?
20	export const engineSurface = (path) =>
21	  ENGINE_DIR_ROOTS.some((r) => path.startsWith(`${r}/`));
22	
23	// Relative import specifiers in ES module source: `from '<spec>'`, side-effect
24	// `import '<spec>'`, and dynamic `import('<spec>')`. Bare specifiers (node
25	// builtins, dependencies) are not relative and never matched. Scanning raw
26	// source is deliberate — no corpus .mjs carries a relative specifier inside a
27	// comment or string that isn't a real module edge, and a parser would be the
28	// kind of dependency the engine refuses to earn.
29	const RELATIVE_SPEC = /(?:\bfrom|\bimport)\s*\(?\s*['"](\.[^'"]+)['"]/g;
30	
31	// Each { spec, line } in the source, 1-indexed so findings can pin the import.
32	export function relativeImports(source) {
33	  const out = [];
34	  for (const m of source.matchAll(RELATIVE_SPEC)) {
35	    out.push({ spec: m[1], line: source.slice(0, m.index).split('\n').length });
36	  }
37	  return out;
38	}
39	
40	// Resolve a relative specifier from a repo-relative file to a repo-relative
41	// target, against a membership oracle `has(path)` (a tracked-file set, or the
42	// canon tree). Extension/index completion mirrors what Node itself would try
43	// for the corpus's module shapes. Returns null when nothing matches — the
44	// caller decides whether that is ignorable (a checker avoiding false
45	// positives) or fatal (a vendor set that would not load).
46	export function resolveRelative(fromFile, spec, has) {
47	  const base = posix.normalize(posix.join(posix.dirname(fromFile), spec));
48	  const candidates = /\.[a-z]+$/i.test(base)
49	    ? [base]
50	    : [base, `${base}.mjs`, `${base}.js`, `${base}/index.mjs`];
51	  return candidates.find(has) ?? null;
52	}
