  });
  const root = makeRepo({ changed: { 'a.txt': 'alpha beta\n# alpha in a skipped line\nbeta\n' } });
  try {
    const findings = rule.run(ctxOf(root));
    assert.deepEqual(findings.map((f) => [f.line, f.what]), [[1, 'alpha'], [3, 'beta']]);
  } finally { cleanup(root); }
});

